/* Original images load only after an image link is activated. Links work without JS. */
(()=>{let dialog,view,image,lastFocus;const restore=()=>{image?.removeAttribute('src');document.body.style.overflow='';lastFocus?.focus()};function init(){dialog=document.createElement('dialog');dialog.className='crawl-media-dialog';dialog.setAttribute('aria-label','안내 이미지 확대');dialog.innerHTML='<div class="crawl-media-toolbar"><p>원본 크기입니다. 좌우·아래로 움직여 내용을 읽으세요.</p><button type="button" data-fit-toggle>화면 너비에 맞추기</button><button type="button" data-close>닫기</button></div><div class="crawl-media-viewport" tabindex="0" aria-label="확대 이미지 이동 영역"><img alt=""></div>';document.body.append(dialog);view=dialog.querySelector('.crawl-media-viewport');image=view.querySelector('img');dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.querySelector('[data-fit-toggle]').addEventListener('click',e=>{const fit=!view.hasAttribute('data-fit');view.toggleAttribute('data-fit',fit);e.currentTarget.textContent=fit?'원본 크기로 보기':'화면 너비에 맞추기'});dialog.addEventListener('close',restore);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}document.addEventListener('click',e=>{const region=e.target.closest('a[href^="#crawl-region-"]');if(region){const search=document.querySelector('#center-search'),select=document.querySelector('#center-region');if(search&&select){search.value='';select.value='all';search.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}))}}const link=e.target.closest('a[data-media-zoom]');if(!link||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||!('HTMLDialogElement' in window))return;e.preventDefault();if(!dialog)init();lastFocus=link;view.removeAttribute('data-fit');dialog.querySelector('[data-fit-toggle]').textContent='화면 너비에 맞추기';image.alt=link.querySelector('img')?.alt||'안내 이미지 원본';image.style.width=link.dataset.fullWidth+'px';image.onload=()=>{view.scrollTop=Number(link.dataset.imageY)||0;view.scrollLeft=0};image.src=link.href;document.body.style.overflow='hidden';dialog.showModal();dialog.querySelector('[data-close]').focus()})})();
